import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [visualSpec]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {{THREE: any}} THREE
 * @property {{loadTexture:(url:string)=>Promise<any>}} textureLoader
 * @property {{emit:(event:string,payload:any)=>void}} emit
 * @property {{primitives:any}} primitives
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{tier?:string}} tier
 */

/**
 * Create the Collection card 3 label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container – the adapter will apply position/rotation/scale.
  const root = new Group();

  // -----------------------------------------------------------------------
  // Geometry & material
  // -----------------------------------------------------------------------
  // Image aspect 512 × 320 ≈ 1.6 : 1, use that for plane size.
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthTest: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the texture asynchronously; the function itself stays synchronous.
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // -----------------------------------------------------------------------
  // Text label
  // -----------------------------------------------------------------------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.visualSpec?.colors?.paper ?? '#e8ecf2'),
      align: 'center',
    });

    // Position the text slightly above the plane to avoid z‑fighting.
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // -----------------------------------------------------------------------
  // Cinematic primitives (none in this spec, but handle generically)
  // -----------------------------------------------------------------------
  const primitiveHandles = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name]?.(root, prim.params);
      if (handler) {
        primitiveHandles.push(handler);
        // If a trigger is defined, we could attach it here, but the spec
        // provides no triggers – we simply keep the handle for cleanup.
      }
    }
  }

  // -----------------------------------------------------------------------
  // UserData – handlers (none) and cleanup
  // -----------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose material and texture.
    if (material.map && typeof material.map.dispose === 'function') {
      material.map.dispose();
    }
    material.dispose();

    // Dispose geometry.
    geometry.dispose();

    // Dispose any primitive resources.
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
      if (h && h.timeline && typeof h.timeline.kill === 'function') {
        h.timeline.kill();
      }
    }

    // Kill any GSAP timelines that might have been created elsewhere.
    if (gsap && typeof gsap.globalTimeline?.clear === 'function') {
      gsap.globalTimeline.clear();
    }

    // Remove all children.
    root.traverse((child) => {
      if (child !== root && child.isMesh) {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      }
    });
  };

  return root;
}
